Thread t = new Thread(() =>
{
    uint itemId = 35943;
    int questId = 12035;
    while (robotManager.Products.Products.IsStarted)
    {
        if (Conditions.InGameAndConnectedAndAliveAndProductStartedNotInPause)
        {
            if (!Quest.HasQuest(questId))
                break;
            if (ObjectManager.Target.IsValid && ObjectManager.Target.IsDead && ObjectManager.Target.Entry == 25623)
            {
                Fight.StopFight();
            wManager.Wow.Helpers.Lua.RunMacroText("/TargetLastEnemy");
                ItemsManager.UseItem(itemId);
            wManager.Wow.Helpers.Lua.RunMacroText("/TargetLastEnemy");
                ItemsManager.UseItem(itemId);
            }
        }
        Thread.Sleep(500);
    }
});
t.Start();

